-- E08 catalogs and schemas: two GCS-backed catalogs, one per storage format
SHOW CATALOGS;
SHOW SCHEMAS FROM delta;
SHOW SCHEMAS FROM hive;

-- E01 Source: 9 physical Parquet datasets
SHOW TABLES FROM hive.source_zone;
SELECT table_name, ordinal_position, column_name, data_type, is_nullable
FROM hive.information_schema.columns
WHERE table_schema = 'source_zone'
ORDER BY table_name, ordinal_position;

-- E02 Bronze
SHOW TABLES FROM delta.bronze_zone;
