-- E06 keys and join columns of the ERD tables
DESCRIBE delta.gold_zone.dim_user;
DESCRIBE delta.gold_zone.dim_account;
DESCRIBE delta.gold_zone.dim_merchant;
DESCRIBE delta.gold_zone.dim_device;
DESCRIBE delta.gold_zone.dim_date;
DESCRIBE delta.gold_zone.fact_transactions;
DESCRIBE delta.gold_zone.fact_login_events;
DESCRIBE delta.gold_zone.fact_balance_snapshot;

-- E07 naming convention: one row per registered table with its layer and Gold role
SELECT table_schema, table_name,
       CASE WHEN table_schema <> 'gold_zone' THEN 'zone-qualified (no prefix)'
            WHEN table_name LIKE 'dim\_%' ESCAPE '\' THEN 'dimension'
            WHEN table_name LIKE 'fact\_%' ESCAPE '\' THEN 'fact'
            WHEN table_name LIKE 'obt\_%' ESCAPE '\' THEN 'one big table'
            WHEN table_name LIKE 'feat\_%' ESCAPE '\' THEN 'feature'
            WHEN table_name LIKE 'opt\_%' ESCAPE '\' THEN 'analytics aggregate'
            ELSE 'unclassified' END AS naming_role
FROM delta.information_schema.tables
WHERE table_schema IN ('bronze_zone', 'silver_zone', 'gold_zone')
ORDER BY table_schema, table_name;

-- E08 provenance: the Delta commit behind one table of each observed run
SELECT version, timestamp, operation FROM delta.bronze_zone."transactions$history";
SELECT version, timestamp, operation FROM delta.silver_zone."transactions$history";
SELECT version, timestamp, operation FROM delta.gold_zone."fact_transactions$history";
SELECT version, timestamp, operation FROM delta.gold_zone."feat_user_behavior$history";
